#!/bin/bash
sed -i 's/val viewModel: NoteViewModel = viewModel(factory = viewModelFactory)/val prefs = getSharedPreferences("user_prefs", android.content.Context.MODE_PRIVATE)\n                    val lastCrash = prefs.getString("last_crash", null)\n                    if (lastCrash != null) {\n                        androidx.compose.foundation.layout.Column(\n                            modifier = Modifier.fillMaxSize().padding(16.dp).androidx.compose.foundation.verticalScroll(androidx.compose.foundation.rememberScrollState())\n                        ) {\n                            androidx.compose.material3.Text("CRASH LOG:", color = androidx.compose.ui.graphics.Color.Red)\n                            androidx.compose.material3.Text(lastCrash, color = androidx.compose.material3.MaterialTheme.colorScheme.onBackground)\n                            androidx.compose.material3.Button(onClick = {\n                                prefs.edit().remove("last_crash").apply()\n                                recreate()\n                            }) {\n                                androidx.compose.material3.Text("Clear")\n                            }\n                        }\n                    } else {\n                        val viewModel: NoteViewModel = viewModel(factory = viewModelFactory)/g' app/src/main/java/com/hyper/note/android/MainActivity.kt
sed -i 's/} // End of NavHost/} \n                    } // End of else block/g' app/src/main/java/com/hyper/note/android/MainActivity.kt
